// 永久来源覆盖/前缀投影坏档门；本夹具只测重放，不冒原业务或Common scope已注册。
#include "resident/domains/growth/growth_market_history.hpp"
#include "resident/domains/growth/growth_model.hpp"
#include "resident/domains/growth/growth_market_history_codec.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool b,const char* s){++checks;if(!b)throw std::runtime_error(s);}
struct Sources final:MarketBusinessCauseRead{const CommonStore& common;Owner owner;Sources(const CommonStore& c,Owner o):common(c),owner(std::move(o)){}Outcome<MarketBusinessCause> market_business_cause(MarketCauseKind kind,const StableId& id)const override{if(kind!=MarketCauseKind::growth_trade||(id!="action:3"&&id!="action:9"))return {false,{},common_failure("MissingTestCause").error};return {true,{common.state().identity,id,kind,id=="action:3"?0:1,{{"market","millet",owner,id=="action:3"?-5:-3}}},{}};}};
MarketMovementRecord movement(const StableId& source,Integer tick,const InventoryView& before,const InventoryView& after,Integer low,Integer high,const ProtectedMarketAccounts& policy){MarketRecipeInventoryTouch touch;touch.inventory_id="market";touch.consume_operations=1;touch.legs={{"market","millet",before.owner,-(before.lots[0].quantity-after.lots[0].quantity)}};auto delta=capture_protected_market_inventory(policy,touch,before,after,low,high);if(!delta.ok)throw std::runtime_error("bad typed fixture capture");MarketMovementRecord record;record.business_fact_id=source;record.source_tick=tick;record.observed_tick=tick;record.steps.push_back({MarketCaptureStage::trade,low,high,{delta.value}});return record;}
}
int main(){try{
    Owner owner{Owner::Kind::organization,"merchant",{}, {}};auto catalog=std::make_shared<CommonCatalog>();catalog->required_inventories.insert("market",{owner,100});catalog->items.insert("millet",ItemDefinition{"millet",1,10});InventoryView initial{"market",owner,100,0,{{"lot:1","millet",{},12,owner,{}}},{}};auto first=initial;first.lots[0].quantity=7;first.revision=1;auto last=first;last.lots[0].quantity=4;last.revision=2;CommonState seed;seed.identity.world_id[0]=1;seed.identity.tick=2;seed.next_instance_id=13;seed.inventories.insert("market",last);seed.facts.insert("action:3",{"action:3","life_activity","growth"});seed.facts.insert("market_history:6",{"market_history:6","growth_market_movement","growth_market_history"});seed.facts.insert("private_shop_day:7",{"private_shop_day:7","private_shop_operating_completed","private_shops"});seed.facts.insert("action:9",{"action:9","life_activity","growth"});seed.facts.insert("market_history:12",{"market_history:12","growth_market_movement","growth_market_history"});CommonStore common(seed,catalog);GrowthCatalog growth;growth.economy=true;growth.regional_life=true;growth.tradeable_items={"millet"};growth.shops.insert("shop",{"shop","place","market","wallet",{}, {}});GrowthMarketHistoryCatalog history;history.shop_ids={"shop"};history.initial_inventories.insert("market",initial);history.initial_next_instance_id=3;ProtectedMarketAccounts policy;policy.inventories.insert("market",{owner,100});GrowthMarketHistoryState state;state.movements.insert("market_history:6",movement("action:3",0,initial,first,4,5,policy));state.movements.insert("market_history:12",movement("action:9",1,first,last,10,11,policy));Sources sources(common,owner);GrowthMarketHistoryAccess access{sources,[](const StableId&,const InventoryView&){return common_success();},[](const std::vector<StableId>& ids)->Outcome<std::vector<StableId>>{if(ids!=std::vector<StableId>{"market"})return {false,{},common_failure("WrongTestInventory").error};return {true,{"action:3","action:9"},{}};}};
    const auto before=encode_common_state(common.state());check(validate_growth_market_history(common,*catalog,growth,history,state,access).ok,"original cause coverage and exact current tail");auto current=read_growth_market_history_current(common,*catalog,growth,history,state,access,"shop","millet");check(current.ok&&current.value.available_stock==4&&current.value.market_revision==2,"current stock from full replay");auto old=read_growth_market_history_before_shop_result(common,*catalog,growth,history,state,access,"shop","millet",0,"private_shop_day:7");check(old.ok&&old.value.available_stock==7&&old.value.market_revision==1,"actual source before day result not current market");check(compare_boundary(before,encode_common_state(common.state())).exact(),"replay changed Common assets or IDs");
    auto json_state=decode_growth_market_history(encode_growth_market_history(state));check(json_state.ok&&validate_growth_market_history(common,*catalog,growth,history,json_state.value,access).ok,"JSON canonical lot field order still matches original typed initial assets");
    auto removed=state;removed.movements.erase("market_history:6");check(!validate_growth_market_history(common,*catalog,growth,history,removed,access).ok,"removed source payload cannot hide");auto changed=state;changed.movements.find("market_history:6")->steps[0].inventories[0].lots[0].after->quantity=8;check(!validate_growth_market_history(common,*catalog,growth,history,changed,access).ok,"self-consistent quantity source cannot replace true cause");common.state().inventories.find("market")->lots[0].quantity=5;check(!validate_growth_market_history(common,*catalog,growth,history,state,access).ok,"unexplained current inventory write");common.state().inventories.find("market")->lots[0].quantity=4;
    auto no_price=access;no_price.trade_before={};check(!validate_growth_market_history(common,*catalog,growth,history,state,no_price).ok,"missing original trade price validation");auto no_source=access;no_source.source_ids=[](const std::vector<StableId>&)->Outcome<std::vector<StableId>>{return {true,{"action:3"},{}};};check(!validate_growth_market_history(common,*catalog,growth,history,state,no_source).ok,"independent complete cause list required");check(!read_growth_market_history_before_shop_result(common,*catalog,growth,history,state,access,"shop","millet",0,"action:3").ok,"arbitrary fact not a day boundary");// 原NPC持点时仍可追加；本口不会错误提交调用者点，失败由调用者同时还原本域。
    auto candidate_seed=seed;candidate_seed.facts.erase("market_history:12");candidate_seed.next_instance_id=12;CommonStore candidate(candidate_seed,catalog);Sources candidate_sources(candidate,owner);auto candidate_access=GrowthMarketHistoryAccess{candidate_sources,access.trade_before,access.source_ids};auto candidate_state=state;candidate_state.movements.erase("market_history:12");const auto candidate_before=encode_common_state(candidate.state());auto point=candidate.begin_savepoint();check(point.ok,"outer NPC savepoint");auto recorded=record_growth_market_movement_in_candidate(candidate,*catalog,growth,history,candidate_state,candidate_access,*state.movements.find("market_history:12"));check(recorded.ok&&recorded.value=="market_history:12","candidate record does not nest existing Common point");check(candidate.rollback_savepoint(point.value).ok,"candidate writer did not commit caller point");check(compare_boundary(candidate_before,encode_common_state(candidate.state())).exact(),"outer rollback restores real fact and ID");
    candidate_state=state;candidate_state.movements.erase("market_history:12");candidate_access.trade_before=[](const StableId& id,const InventoryView&){return id=="action:9"?common_failure("LateTradeSourceFailure"):common_success();};point=candidate.begin_savepoint();recorded=record_growth_market_movement_in_candidate(candidate,*catalog,growth,history,candidate_state,candidate_access,*state.movements.find("market_history:12"));check(!recorded.ok,"late source failure invalidates candidate");check(candidate.rollback_savepoint(point.value).ok,"caller can roll back late source failure");candidate_state=state;candidate_state.movements.erase("market_history:12");check(compare_boundary(candidate_before,encode_common_state(candidate.state())).exact(),"failed candidate fact and ID fully rolled back");
    std::cout<<"GROWTH_MARKET_HISTORY "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_MARKET_HISTORY "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
